private static <K extends MediaSessionImpl> SessionTask<ListenableFuture<Void>, K> sendSessionResultWhenReady(SessionTask<ListenableFuture<SessionResult>, K> task) {
  return (sessionImpl, controller, sequenceNumber) -> handleSessionTaskWhenReady(sessionImpl, controller, sequenceNumber, task, future -> {
    SessionResult result;
    try {
      try {
        result = checkNotNull(future.get(), "SessionResult must not be null");
      } catch (NullPointerException e) {
        Log.w(TAG, "SessionResult is null", e);
        result = new SessionResult(SessionResult.RESULT_ERROR_UNKNOWN);
      }
    } catch (CancellationException e) {
      Log.w(TAG, "Session operation cancelled", e);
      result = new SessionResult(SessionResult.RESULT_INFO_SKIPPED);
    } catch (ExecutionException | InterruptedException exception) {
      Log.w(TAG, "Session operation failed", exception);
      result = new SessionResult(exception.getCause() instanceof UnsupportedOperationException ? SessionResult.RESULT_ERROR_NOT_SUPPORTED : SessionResult.RESULT_ERROR_UNKNOWN);
    }
    sendSessionResult(controller, sequenceNumber, result);
  });
}
